CREATE TABLE member_profiles (user_id BIGINT PRIMARY KEY, member_rank VARCHAR(16) NOT NULL DEFAULT 'S_NEW', accumulated_spending DECIMAL(15,0) NOT NULL DEFAULT 0, points_balance BIGINT NOT NULL DEFAULT 0, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, CHECK(points_balance>=0 AND accumulated_spending>=0));
CREATE TABLE point_transactions (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, order_id BIGINT NOT NULL UNIQUE, points_delta BIGINT NOT NULL, occurred_at DATETIME(6) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE);
CREATE TABLE warranty_cards (id BIGINT AUTO_INCREMENT PRIMARY KEY, imei_number VARCHAR(40) NOT NULL UNIQUE, order_id BIGINT NOT NULL, customer_id BIGINT NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, warranty_type VARCHAR(80) NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY(customer_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE repair_tickets (id BIGINT AUTO_INCREMENT PRIMARY KEY, warranty_id BIGINT NOT NULL, issue VARCHAR(500) NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'RECEIVED', created_at DATETIME(6) NOT NULL, FOREIGN KEY(warranty_id) REFERENCES warranty_cards(id) ON DELETE CASCADE);
